const allowed = {
  kind: ['real_work', 'lab_demo', 'lesson', 'opinion', 'publication'],
  proof: ['verified', 'self_reported', 'demo', 'idea'],
  confidentiality: ['public', 'anonymize', 'private'],
};

const input = $json;
const required = ['title', 'kind', 'situation', 'action_text', 'proof_level', 'confidentiality'];
for (const key of required) {
  if (!String(input[key] ?? '').trim()) throw new Error(`Eksik alan: ${key}`);
}
if (!allowed.kind.includes(input.kind)) throw new Error('Gecersiz kind');
if (!allowed.proof.includes(input.proof_level)) throw new Error('Gecersiz proof_level');
if (!allowed.confidentiality.includes(input.confidentiality)) throw new Error('Gecersiz confidentiality');
if (input.kind === 'lab_demo' && input.proof_level !== 'demo') {
  throw new Error('lab_demo icin proof_level demo olmalidir');
}
if (input.proof_level === 'idea' && input.kind === 'real_work') {
  throw new Error('idea kanit seviyesi real_work olarak kaydedilemez');
}
const approvedClaims = String(input.approved_claims_text ?? '')
  .split(/\r?\n/)
  .map((value) => value.trim())
  .filter(Boolean);
const tags = String(input.tags_text ?? '')
  .split(',')
  .map((value) => value.trim().toLowerCase())
  .filter(Boolean);

return [{ json: {
  title: String(input.title).trim(),
  kind: input.kind,
  situation: String(input.situation).trim(),
  action_text: String(input.action_text).trim(),
  result_text: String(input.result_text ?? '').trim() || null,
  source_ref: String(input.source_ref ?? '').trim() || null,
  proof_level: input.proof_level,
  confidentiality: input.confidentiality,
  approved_claims: approvedClaims,
  tags,
} }];
